"""Aggregate report and static dashboard for the exploratory GUIDE rerun."""
import json,hashlib,html
from pathlib import Path
import matplotlib.pyplot as plt
from .guide_rerun_v2 import ROOT,OUT,PRIVATE,KS
from .phase2 import sha256_file

def load(name):return json.loads((OUT/name).read_text(encoding='utf-8'))
def run():
 p=load('preparation.json');v=load('validation.json');h=load('holdout_metrics.json');c=load('correlation_holdout.json');cv=load('correlation_validation.json');ops=load('api_operations.json')
 lines=['# GUIDE_Test exploratory rerun v2','',f"Source rows: GUIDE_Test.csv; {p['ranking_candidates']:,} oracle-group incident candidates and {p['unambiguous_alerts']:,} unambiguous alerts from 469 selected organizations.",'','## Ranking validation','',f"Selected logistic C={v['selected_C']}. The first tested K meeting >=95% macro candidate recall was K={v['selected_candidate_K']}; this means up to 500 candidate incidents per organization. This is a retrieval workload measure, not final Recall@20.",'','| Candidate K | Validation recall | Holdout recall |','|---:|---:|---:|']
 for k in KS:lines.append(f"| {k} | {v['candidate_recall_curve'][str(k)]['recall']['mean']:.4f} | {h['candidate_recall_curve'][str(k)]['mean']:.4f} |")
 lines+=['','## Holdout ranking (68 exploratory organizations)','', '| Method | Precision@10 | Recall@20 | nDCG@20 rank 1 high | nDCG@20 rank 20 high |','|---|---:|---:|---:|---:|']
 for method,m in h['methods'].items():lines.append(f"| {method} | {m['precision_at_10']['mean']:.4f} | {m['recall_at_20']['mean']:.4f} | {m['ndcg_at_20_rank1_highest']['mean']:.4f} | {m['ndcg_at_20_rank20_highest_sensitivity']['mean']:.4f} |")
 lines+=['',f"Groq calls: {ops['requests']}; actual tokens: {ops['actual_tokens']:,}; statuses: {ops['statuses']}. Missing/invalid Groq output falls back to fused offline ordering and must be interpreted with the fallback fraction. Model: openai/gpt-oss-120b. Token usage is measured; billing tier and zero cost were not verified.",'','## Correlation diagnostic (500 label-blind selected alerts per organization)','',f"Validation best tested candidate recall: {cv['curve'][str(cv['selected_neighbors_per_route'])]['micro_candidate_recall']:.4f}; target met: {cv['target_met']}. Holdout candidate recall: {c['micro']['candidate_recall']:.4f}; candidate coverage: {c['micro']['candidate_coverage']:.4f}. Final pair precision: {c['micro']['precision']:.4f}; recall: {c['micro']['recall']:.4f}; F1: {c['micro']['f1']:.4f}.",'','## Interpretation and data controls','','This run uses the local GUIDE_Test data and queue labels. Ranking incident candidates were formed by the dataset IncidentId and are an oracle-group diagnostic; no end-to-end C/P/V grouping or military certification is demonstrated. The 30 previously evaluated organizations were excluded. The 68 new holdout organizations are exploratory because complete prior label-exposure evidence is unavailable. Model and candidate settings were selected on training/validation only and frozen before holdout label access. QueueRank numeric direction and the exact publisher active queue remain unverified; both nDCG directions are reported.','', 'All 70,702 conflicting alert keys were excluded from feature construction; correlation truth uses only unambiguous keys. The correlation estimate is restricted to 500 opaque-hash-selected alerts per organization. The hosted prompts contained only Category, MitreTechniques, EntityType, EvidenceRole and temporary candidate numbers. No raw IDs, evaluator labels, or entity values were sent. Groq may retain inference inputs for reliability/abuse monitoring for up to 30 days unless ZDR is enabled (see provider documentation).','',f"Raw source hashes: `{p['raw_hashes']}`. Prediction freeze and restricted artifacts are in ignored `data/derived/guide_rerun_v2`; aggregate outputs are in `outputs/guide_rerun_v2`.",'']
 lines+=['','## Retrieval-to-reranking limit','',f"The Groq request contained only the top 50 fused candidates. The holdout candidate recall ceiling at K=50 was {h['candidate_recall_curve']['50']['mean']:.4f}; the 95% target at K=500 therefore does not transfer to Groq Recall@20.",f"The highest observed offline Recall@20 was logistic {h['methods']['logistic']['recall_at_20']['mean']:.4f}; Groq achieved {h['methods']['groq_rerank']['recall_at_20']['mean']:.4f}. These post-evaluation observations cannot be used to claim a confirmatory model selection.",'']
 (OUT/'report.md').write_text('\n'.join(lines),encoding='utf-8')
 ks=KS;plt.figure(figsize=(7,4));plt.plot(ks,[v['candidate_recall_curve'][str(k)]['recall']['mean'] for k in ks],marker='o',label='validation');plt.plot(ks,[h['candidate_recall_curve'][str(k)]['mean'] for k in ks],marker='o',label='holdout');plt.axhline(.95,color='red',linestyle='--',label='95% target');plt.xlabel('Candidates per organization');plt.ylabel('Top-20 candidate recall');plt.legend();plt.tight_layout();plt.savefig(OUT/'candidate_recall_curve.png',dpi=150);plt.close()
 names=list(h['methods']);plt.figure(figsize=(8,4));plt.bar(names,[h['methods'][n]['recall_at_20']['mean'] for n in names]);plt.xticks(rotation=30,ha='right');plt.ylabel('Macro Recall@20');plt.tight_layout();plt.savefig(OUT/'method_recall20.png',dpi=150);plt.close()
 payload={'ranking':{n:{k:m[k]['mean'] for k in ['precision_at_10','recall_at_20','ndcg_at_20_rank1_highest','ndcg_at_20_rank20_highest_sensitivity']} for n,m in h['methods'].items()},'candidate':{k:{'validation':v['candidate_recall_curve'][k]['recall']['mean'],'holdout':h['candidate_recall_curve'][k]['mean']} for k in map(str,KS)},'correlation':{k:c['micro'][k] for k in ['precision','recall','f1','candidate_recall','candidate_coverage']},'groq_status':ops['statuses'],'organizations':68}
 data=json.dumps(payload,separators=(',',':')).replace('</','<\\/')
 page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GUIDE exploratory rerun</title><style>body{font:16px system-ui;background:#0b1020;color:#eef3ff;max-width:1000px;margin:auto;padding:28px}h1{font-size:2.2rem}.note{background:#302514;padding:15px;border-radius:8px}section{background:#172039;padding:18px;margin:16px 0;border-radius:10px}select{padding:8px;background:#111827;color:white}table{border-collapse:collapse;width:100%}td,th{padding:9px;text-align:left;border-bottom:1px solid #334155}.bar{background:#334155;border-radius:8px;height:14px}.bar span{display:block;background:#38bdf8;height:100%;border-radius:8px}small{color:#cbd5e1}</style></head><body><h1>GUIDE_Test exploratory rerun</h1><p class="note">68 organizations. Ranking uses oracle incident groups. Correlation uses 500 selected alerts per organization. No military certification or confirmed 95% final recall.</p><section><h2>Ranking method</h2><select id="method"></select><div id="metrics"></div></section><section><h2>Candidate retrieval</h2><div id="candidates"></div></section><section><h2>Correlation</h2><div id="correlation"></div></section><section><h2>Groq calls</h2><div id="groq"></div></section><small>All values are aggregate. Previous exposure makes this holdout exploratory. See report.md for provenance and limits.</small><script>const d=__DATA__;const s=document.getElementById('method');Object.keys(d.ranking).forEach(k=>s.add(new Option(k,k)));function row(k,v){return `<tr><td>${k}</td><td>${(100*v).toFixed(2)}%</td></tr>`}function show(){document.getElementById('metrics').innerHTML='<table>'+Object.entries(d.ranking[s.value]).map(([k,v])=>row(k,v)).join('')+'</table>'}s.onchange=show;show();document.getElementById('candidates').innerHTML='<table><tr><th>K</th><th>Validation</th><th>Holdout</th></tr>'+Object.entries(d.candidate).map(([k,v])=>`<tr><td>${k}</td><td>${(100*v.validation).toFixed(2)}%</td><td>${(100*v.holdout).toFixed(2)}%</td></tr>`).join('')+'</table>';document.getElementById('correlation').innerHTML='<table>'+Object.entries(d.correlation).map(([k,v])=>row(k,v)).join('')+'</table>';document.getElementById('groq').textContent=JSON.stringify(d.groq_status);</script></body></html>'''.replace('__DATA__',data)
 (ROOT/'dashboard/guide_rerun_v2.html').write_text(page,encoding='utf-8')
 manifest={'classification':'exploratory','inputs':{n:sha256_file(OUT/n) for n in ['preparation.json','validation.json','method_freeze.json','prediction_freeze.json','holdout_metrics.json','correlation_validation.json','correlation_freeze.json','correlation_prediction_freeze.json','correlation_holdout.json','api_operations.json']},'outputs':{n:sha256_file(OUT/n) for n in ['report.md','candidate_recall_curve.png','method_recall20.png']},'dashboard_sha256':sha256_file(ROOT/'dashboard/guide_rerun_v2.html'),'external_model':'Groq openai/gpt-oss-120b','actual_tokens':ops['actual_tokens'],'raw_hashes':p['raw_hashes']};(OUT/'run_manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
 print('report and dashboard written')
if __name__=='__main__':run()
